-- ============================================================
-- V1: ESQUEMA INICIAL DE LA BASE DE DATOS
-- Sistema de Créditos y Cobranzas - PostgreSQL
-- ============================================================

CREATE TABLE clientes (
  "id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY NOT NULL,
  "nombre_cliente" varchar(150) NOT NULL,
  "telefono_cliente" varchar(30),
  "fecha_creacion" timestamp NOT NULL
);

CREATE TABLE "cobradores" (
  "id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY NOT NULL,
  "nombre_cobrador" varchar(150) NOT NULL,
  "telefono_cobrador" varchar(30),
  "activo" boolean NOT NULL DEFAULT true,
  "fecha_creacion" timestamp NOT NULL
);

CREATE TABLE "creditos" (
  "id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY NOT NULL,
  "credito_origen_id" integer UNIQUE,
  "cliente_id" integer NOT NULL,
  "cobrador_id" integer NOT NULL,
  "monto" decimal(12,2) NOT NULL,
  "fecha_inicio" date NOT NULL,
  "fecha_limite" date NOT NULL,
  "frecuencia_pago" varchar(20) NOT NULL,
  "tasa_interes" decimal(5,2) NOT NULL,
  "estado" varchar(20) NOT NULL DEFAULT 'AL_DIA',
  CONSTRAINT chk_frecuencia_pago CHECK (frecuencia_pago IN ('DIARIA', 'SEMANAL', 'QUINCENAL', 'MENSUAL')),
  CONSTRAINT chk_tasa_interes    CHECK (tasa_interes IN (5.00, 10.00, 20.00)),
  CONSTRAINT chk_fechas_credito  CHECK (fecha_limite > fecha_inicio)
);

CREATE OR REPLACE FUNCTION obtener_tasa_interes_credito(p_inicio date, p_limite date)
RETURNS decimal(5,2)
LANGUAGE plpgsql
IMMUTABLE
STRICT
AS $$
DECLARE
  v_meses integer;
BEGIN
  IF p_limite = p_inicio + 7 THEN
    RETURN 5.00;
  ELSIF p_limite = p_inicio + 15 THEN
    RETURN 10.00;
  END IF;

  v_meses := (EXTRACT(YEAR FROM p_limite) - EXTRACT(YEAR FROM p_inicio)) * 12
           + EXTRACT(MONTH FROM p_limite) - EXTRACT(MONTH FROM p_inicio);
  IF v_meses >= 1
     AND (p_inicio + make_interval(months => v_meses))::date = p_limite THEN
    RETURN 20.00;
  END IF;

  RAISE EXCEPTION
    'Plazo no permitido: use 7 días, 15 días o un número entero de meses.';
END;
$$;

CREATE OR REPLACE FUNCTION asignar_tasa_interes_credito()
RETURNS trigger
LANGUAGE plpgsql
AS $$
BEGIN
  NEW.tasa_interes := obtener_tasa_interes_credito(NEW.fecha_inicio, NEW.fecha_limite);
  RETURN NEW;
END;
$$;

CREATE TRIGGER trg_asignar_tasa_interes_credito
BEFORE INSERT OR UPDATE ON creditos
FOR EACH ROW
EXECUTE FUNCTION asignar_tasa_interes_credito();

CREATE TABLE "cuotas" (
  "id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY NOT NULL,
  "credito_id" integer NOT NULL,
  "numero_cuota" integer NOT NULL,
  "monto_cuota" decimal(12,2) NOT NULL,
  "fecha_vencimiento" date NOT NULL,
  "estado" varchar(20) NOT NULL DEFAULT 'PENDIENTE'
);

CREATE TABLE "gestiones_cobro" (
  "id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY NOT NULL,
  "credito_id" integer NOT NULL,
  "cuota_id" integer NOT NULL,
  "fecha_gestion" timestamp NOT NULL,
  "tipo_gestion" varchar(30) NOT NULL,
  "resultado" varchar(100),
  "observaciones" text
);

CREATE TABLE "pagos" (
  "id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY NOT NULL,
  "cuota_id" integer NOT NULL,
  "gestion_cobro_id" integer,
  "monto" decimal(12,2) NOT NULL,
  "fecha_pago" timestamp NOT NULL
);

CREATE UNIQUE INDEX ON "cuotas" ("credito_id", "numero_cuota");

ALTER TABLE "creditos" ADD FOREIGN KEY ("cliente_id")        REFERENCES "clientes"  ("id") DEFERRABLE INITIALLY IMMEDIATE;
ALTER TABLE "creditos" ADD FOREIGN KEY ("cobrador_id")       REFERENCES "cobradores" ("id") DEFERRABLE INITIALLY IMMEDIATE;
ALTER TABLE "creditos" ADD FOREIGN KEY ("credito_origen_id") REFERENCES "creditos"  ("id") DEFERRABLE INITIALLY IMMEDIATE;
ALTER TABLE "cuotas"   ADD FOREIGN KEY ("credito_id")        REFERENCES "creditos"  ("id") DEFERRABLE INITIALLY IMMEDIATE;
ALTER TABLE "pagos"    ADD FOREIGN KEY ("cuota_id")          REFERENCES "cuotas"    ("id") DEFERRABLE INITIALLY IMMEDIATE;
ALTER TABLE "gestiones_cobro" ADD FOREIGN KEY ("credito_id") REFERENCES "creditos"  ("id") DEFERRABLE INITIALLY IMMEDIATE;
ALTER TABLE "gestiones_cobro" ADD FOREIGN KEY ("cuota_id")   REFERENCES "cuotas"    ("id") DEFERRABLE INITIALLY IMMEDIATE;
ALTER TABLE "pagos"    ADD FOREIGN KEY ("gestion_cobro_id")  REFERENCES "gestiones_cobro" ("id") DEFERRABLE INITIALLY IMMEDIATE;
